insert into public.products (id, slug, name, type, summary, description, price, regular_price, price_max, on_sale, in_stock, images, category_ids, attributes, variations, permalink, menu_order) values (6251, 'customized-mens-gift-hamper', 'Customized Men’s Gift Hamper', 'simple', 'Introducing our Custom Men’s Gift Hamper – where style meets personalization. Curated with sophistication, it’s filled with handpicked essentials tailored to the modern man. From engraved accessories to gourmet treats, make a statement with a gift that reflects his unique taste and personality. Email at us for customizing the hamper the way you like.. Email: contact@ecocart.co.in', 'Introducing our Customized Men’s Gift Hamper – the perfect blend of sophistication and personal touch. Tailored to suit the discerning tastes of the modern man, each hamper is meticulously curated with handpicked essentials that exude style and charm.

