insert into public.products (id, slug, name, type, summary, description, price, regular_price, price_max, on_sale, in_stock, images, category_ids, attributes, variations, permalink, menu_order) values (6099, 'flower-bouquet', 'Flower Bouquet', 'simple', 'Presenting our exquisite Flower Bouquet – a delicate symphony of nature’s finest blooms. Handcrafted with care and artistry, each bouquet is a masterpiece of color and fragrance, sure to captivate the senses and stir the heart. Whether it’s a gesture of love, appreciation, or celebration, our Flower Bouquet is the perfect way to convey your emotions with beauty and grace. Let these blossoms tell y', 'Step into a world of floral elegance with our stunning Flower Bouquet – a breathtaking display of nature’s most exquisite blooms meticulously arranged to captivate hearts and inspire awe. Each bouquet is a celebration of color, texture, and fragrance, carefully curated by our expert florists to evoke emotions and create unforgettable moments.

Dive into a palette of vibrant hues, from the soft pastels of roses to the bold brilliance of lilies, each stem selected for its pristine beauty and lasting freshness. Whether it’s a romantic gesture, a token of appreciation, or a joyful celebration, our Flower Bouquet is the perfect expression of your sentiments.

Indulge your senses as you bask in the delicate fragrance and marvel at the intricate interplay of petals and foliage. With every bloom handpicked and lovingly arranged, our Flower Bouquet is more than just a gift – it’s a work of art, a testament to the beauty and wonder of nature.

Embrace the magic of the moment and let our Flower Bouquet weave its spell, creating memories that will last a lifetime. Whether adorning a tabletop, brightening a room, or conveying your deepest emotions, our bouquet is sure to leave a lasting impression, bringing joy and beauty to any occasion.', 55000, 55000, null, false, true, '[{"src": "https://ecocart.co.in/wp-content/uploads/2024/05/creatella_2-15-05-2024-0005.jpg", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/creatella_2-15-05-2024-0005-500x667.jpg", "alt": "Flower Bouquet"}, {"src": "https://ecocart.co.in/wp-content/uploads/2024/05/creatella_2-15-05-2024-0004.jpg", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/creatella_2-15-05-2024-0004-500x667.jpg", "alt": "Flower Bouquet"}]'::jsonb, '{138}'::integer[], '[]'::jsonb, '[]'::jsonb, 'https://ecocart.co.in/product/flower-bouquet/', 87) on conflict (id) do update set slug = excluded.slug, name = excluded.name, type = excluded.type, summary = excluded.summary, description = excluded.description, price = excluded.price, regular_price = excluded.regular_price, price_max = excluded.price_max, on_sale = excluded.on_sale, in_stock = excluded.in_stock, images = excluded.images, category_ids = excluded.category_ids, attributes = excluded.attributes, variations = excluded.variations, permalink = excluded.permalink, menu_order = excluded.menu_order, synced_at = now();
insert into public.products (id, slug, name, type, summary, description, price, regular_price, price_max, on_sale, in_stock, images, category_ids, attributes, variations, permalink, menu_order) values (6087, 'wallet', 'Customized Wallet with Name Plate', 'simple', 'Introducing our Custom Wallet – where style meets functionality. Crafted with premium materials, personalize it with your initials or a special message. With ample space for cards and cash, it’s the perfect blend of practicality and personality. Elevate your everyday carry with our Custom Wallet. Email at us for etching your initials,name or dates on the wallet. Email: contact@ecocart.co.in', 'Introducing our Customized Wallet – where functionality meets personal style. Crafted with premium materials and meticulous attention to detail, this wallet is not just an accessory, but a reflection of your unique personality.

Customize it with your initials, a meaningful date, or a special message to create a one-of-a-kind piece that speaks volumes about who you are. With multiple compartments for cards, cash, and coins, this wallet seamlessly blends practicality with individuality.

Whether it’s a gift for yourself or a loved one, our Customized Wallet is sure to make a statement while keeping your essentials organized and secure. Upgrade your everyday carry with a touch of personal flair – because your wallet should be as unique as you are.', 45000, 55000, null, true, true, '[{"src": "https://ecocart.co.in/wp-content/uploads/2024/05/craft_by_architect-15-05-2024-0002_1-transformed.jpeg", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/craft_by_architect-15-05-2024-0002_1-transformed-500x667.jpeg", "alt": "Customized Wallet with Name Plate"}, {"src": "https://ecocart.co.in/wp-content/uploads/2024/05/craft_by_architect-15-05-2024-0001-transformed.jpeg", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/craft_by_architect-15-05-2024-0001-transformed-500x667.jpeg", "alt": "Customized Wallet with Name Plate"}, {"src": "https://ecocart.co.in/wp-content/uploads/2024/05/craft_by_architect-15-05-2024-0003-transformed.png", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/craft_by_architect-15-05-2024-0003-transformed-500x667.png", "alt": "Customized Wallet with Name Plate"}]'::jsonb, '{138}'::integer[], '[]'::jsonb, '[]'::jsonb, 'https://ecocart.co.in/product/wallet/', 88) on conflict (id) do update set slug = excluded.slug, name = excluded.name, type = excluded.type, summary = excluded.summary, description = excluded.description, price = excluded.price, regular_price = excluded.regular_price, price_max = excluded.price_max, on_sale = excluded.on_sale, in_stock = excluded.in_stock, images = excluded.images, category_ids = excluded.category_ids, attributes = excluded.attributes, variations = excluded.variations, permalink = excluded.permalink, menu_order = excluded.menu_order, synced_at = now();
insert into public.products (id, slug, name, type, summary, description, price, regular_price, price_max, on_sale, in_stock, images, category_ids, attributes, variations, permalink, menu_order) values (6079, 'choco-bouquet', 'Choco Bouquet – KitKat or Galaxy Chocolate Bouquet', 'variable', 'Delight in our Choco Bouquet, a stunning arrangement of exquisite chocolates beautifully crafted into a bouquet. Perfect for any occasion, this delectable gift combines elegance and indulgence, sure to impress and satisfy chocolate lovers. Treat someone special to a bouquet that’s as sweet as it is memorable.', 'Elevate the art of gifting with our Choco Bouquet – a delectable ensemble of indulgence and elegance. Each stem blossoms with rich, velvety chocolates, intricately arranged to delight the senses and sweeten every occasion. Whether it’s a celebration or a token of appreciation, this exquisite bouquet is sure to leave a lasting impression, making every moment memorable and oh-so-sweet.', 55000, 65000, 125000, true, true, '[{"src": "https://ecocart.co.in/wp-content/uploads/2024/05/1715933166771.jpg", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/1715933166771-500x667.jpg", "alt": "Choco Bouquet – KitKat or Galaxy Chocolate Bouquet"}, {"src": "https://ecocart.co.in/wp-content/uploads/2024/05/creatella_2-15-05-2024-0003.jpg", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/creatella_2-15-05-2024-0003-500x667.jpg", "alt": "Choco Bouquet – KitKat or Galaxy Chocolate Bouquet"}, {"src": "https://ecocart.co.in/wp-content/uploads/2024/05/1715933091855.jpg", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/1715933091855-500x667.jpg", "alt": "Choco Bouquet – KitKat or Galaxy Chocolate Bouquet"}]'::jsonb, '{138}'::integer[], '[{"name": "size", "terms": ["L", "M", "S"]}]'::jsonb, '[{"id": 6294, "attrs": {"size": "s"}, "price": 55000}, {"id": 6295, "attrs": {"size": "m"}, "price": 80000}, {"id": 6296, "attrs": {"size": "l"}, "price": 125000}]'::jsonb, 'https://ecocart.co.in/product/choco-bouquet/', 89) on conflict (id) do update set slug = excluded.slug, name = excluded.name, type = excluded.type, summary = excluded.summary, description = excluded.description, price = excluded.price, regular_price = excluded.regular_price, price_max = excluded.price_max, on_sale = excluded.on_sale, in_stock = excluded.in_stock, images = excluded.images, category_ids = excluded.category_ids, attributes = excluded.attributes, variations = excluded.variations, permalink = excluded.permalink, menu_order = excluded.menu_order, synced_at = now();
insert into public.products (id, slug, name, type, summary, description, price, regular_price, price_max, on_sale, in_stock, images, category_ids, attributes, variations, permalink, menu_order) values (6072, 'red-love', 'Red Love KitKat Chocolate Hamper', 'variable', 'Indulge in the sweet embrace of “Red Love” – our irresistible KitKat chocolate hamper, designed to ignite passion in every bite. Nestled within, you’ll discover a symphony of crunchy wafer and smooth milk chocolate, wrapped in vibrant red packaging that exudes warmth and affection. Treat yourself or surprise someone special with this delightful hamper, perfect for sharing moments of love and joy.', 'Indulge in the sweet embrace of “Red Love” – our irresistible KitKat chocolate hamper, designed to ignite passion in every bite. Nestled within, you’ll discover a symphony of crunchy wafer and smooth milk chocolate, wrapped in vibrant red packaging that exudes warmth and affection. Treat yourself or surprise someone special with this delightful hamper, perfect for sharing moments of love and joy.', 60000, 75000, 120000, true, true, '[{"src": "https://ecocart.co.in/wp-content/uploads/2024/05/IMG-20240415-WA0020-removebg-preview-transformed.png", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/IMG-20240415-WA0020-removebg-preview-transformed-500x667.png", "alt": "Red Love KitKat Chocolate Hamper"}]'::jsonb, '{138}'::integer[], '[{"name": "size", "terms": ["L", "M", "S"]}]'::jsonb, '[{"id": 6075, "attrs": {"size": "m"}, "price": 85000}, {"id": 6077, "attrs": {"size": "s"}, "price": 60000}, {"id": 6078, "attrs": {"size": "l"}, "price": 120000}]'::jsonb, 'https://ecocart.co.in/product/red-love/', 90) on conflict (id) do update set slug = excluded.slug, name = excluded.name, type = excluded.type, summary = excluded.summary, description = excluded.description, price = excluded.price, regular_price = excluded.regular_price, price_max = excluded.price_max, on_sale = excluded.on_sale, in_stock = excluded.i