insert into public.products (id, slug, name, type, summary, description, price, regular_price, price_max, on_sale, in_stock, images, category_ids, attributes, variations, permalink, menu_order) values (6037, 'deluxe-diaper-hamper', 'Deluxe Diaper Hamper – Newborn Baby Gift', 'variable', 'Introducing our Diaper Essentials Hamper – the all-in-one solution for stress-free diaper changes. Inside, you’ll find premium diapers with superior absorbency and leak protection, alongside gentle wipes and soothing diaper rash cream. Simplify your routine and keep your baby happy and comfortable with this essential collection.', 'Introducing our Deluxe Diaper Hamper, the ultimate solution for new parents seeking convenience and comfort. This meticulously curated hamper is designed to make diaper changes a breeze while keeping your little one feeling snug and secure.

Inside this thoughtfully assembled hamper, you’ll find everything you need to tackle those messy moments with ease. Our premium diapers boast superior absorbency and leak protection, ensuring your baby stays dry and happy throughout the day and night. Crafted from soft, breathable materials, these diapers provide gentle comfort for your baby’s delicate skin, reducing the risk of irritation and discomfort.

But that’s not all – our Deluxe Diaper Hamper also includes a selection of essential diapering accessories to simplify your routine. From gentle wipes infused with soothing ingredients to diaper rash cream that offers quick relief, we’ve thought of everything to keep your baby clean, comfortable, and content.

Whether you’re a seasoned parent or embarking on the exciting journey of parenthood for the first time, our Deluxe Diaper Hamper is your go-to solution for hassle-free diaper changes. Treat yourself or surprise a loved one with this indispensable collection of diapering essentials – because when it comes to caring for your little one, only the best will do.', 55000, 65000, 100000, true, true, '[{"src": "https://ecocart.co.in/wp-content/uploads/2024/05/IMG-20240415-WA0018.jpg", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/IMG-20240415-WA0018-500x667.jpg", "alt": "Deluxe Diaper Hamper – Newborn Baby Gift"}, {"src": "https://ecocart.co.in/wp-content/uploads/2024/05/creatella_2-15-05-2024-0002.jpg", "thumb": "https://ecocart.co.in/wp-content/uploads/2024/05/creatella_2-15-05-2024-0002-500x667.jpg", "alt": "Deluxe Diaper Hamper – Newborn Baby Gift"}]'::jsonb, '{138}'::integer[], '[{"name": "size", "terms": ["L", "M", "S"]}]'::jsonb, '[{"id": 6047, "attrs": {"size": "s"}, "price": 55000}, {"id": 6048, "attrs": {"size": "m"}, "price": 80000}, {"id": 6049, "attrs": {"size": "l"}, "price": 100000}]'::jsonb, 'https://ecocart.co.in/product/deluxe-diaper-hamper/', 91) on conflict (id) do update set slug = excluded.slug, name = excluded.name, type = excluded.type, summary = excluded.summary, description = excluded.description, price = excluded.price, regular_price = excluded.regular_price, price_max = excluded.price_max, on_sale = excluded.on_sale, in_stock = excluded.in_stock, images = excluded.images, category_ids = excluded.category_ids, attributes = excluded.attributes, variations = excluded.variations, permalink = excluded.permalink, menu_order = excluded.menu_order, synced_at = now();
